select s.stuno, s.name, s.id, s.grade, s.jumin, s.birthday, s.tel, s.height, s.weight, d.dname as "deptName", p.name as "professorName" from stu s join department d on s.deptno1 = d.deptno join professor p on p.profno = s.profno
s.name LIKE '%' || #{keyword} || '%'
AND s.deptno1 = #{deptNo}
